package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.rules.srd.SrdAuthoring;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.PlayerSkinDrawer;
import net.minecraft.client.gui.screen.Screen;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;
import static dev.tacticalcombat.uiapi.UiApiService.Operation.*;

/** Retained local editing buffers; only complete server acknowledgements publish saved state. */
public final class CharacterWizardScreen extends RpgScreen {
    private final String character;
    private final CreatorDraftState state;
    private JsonObject validation;
    private CreatorFlow.Step step=CreatorFlow.Step.IDENTITY,displayed=step;
    private CharacterShell.Layout layout;
    private CharacterCanvas pane;
    private SectionRail rail;
    private CreatorSheetView sheet;
    private final Map<CreatorFlow.Step,Integer> positions=new EnumMap<>(CreatorFlow.Step.class);
    private final Map<CreatorFlow.Step,String> focus=new EnumMap<>(CreatorFlow.Step.class);
    private final Map<CreatorFlow.Step,Map<String,Integer>> cursors=new EnumMap<>(CreatorFlow.Step.class);
    private RpgButton nextButton,saveButton;
    private boolean fresh;
    private ClassChangeIntent unresolvedClassChange;
    private final DeferredCreatorAction resumed=new DeferredCreatorAction();
    public CharacterWizardScreen(Screen parent,JsonObject snapshot){super("Create Character",parent);character=text(snapshot,"id");state=new CreatorDraftState(DraftReplies.snapshot(snapshot,character));}
    @Override protected boolean hasUnsavedChanges(){return state.dirty();}
    @Override protected int maximumWidth(){return 980;}
    @Override protected void init(){remember();super.init();layout=CharacterShell.layout(frame);pane=null;sheet=null;busy=false;fresh=false;
        rail=addDrawableChild(new SectionRail(layout.rail(),Arrays.stream(CreatorFlow.Step.values()).map(s->new SectionRail.Item(s.name(),s.title)).toList(),s->navigateTab(CreatorFlow.Step.valueOf(s)),28));
        footer();
        saveButton=footerAction("Save Draft",0,()->saveCurrent(()->{message="Draft saved.";build();}));
        nextButton=footerAction(step==CreatorFlow.Step.REVIEW?"Finish Character":"Next",1,()->{if(step==CreatorFlow.Step.REVIEW)finish();else go(CreatorFlow.Step.values()[Math.min(step.ordinal()+1,CreatorFlow.Step.values().length-1)]);});
        footerAction("Refresh",2,this::reload);build();reload();
    }
    private void remember(){if(pane!=null){positions.put(displayed,pane.position());focus.put(displayed,pane.focusedKey());cursors.put(displayed,pane.cursors());}if(sheet!=null)positions.put(displayed,sheet.position());}
    private void build(){remember();if(pane!=null)remove(pane);if(sheet!=null)remove(sheet);sheet=null;displayed=step;rail.selected(step.name());if(nextButton!=null)nextButton.setMessage(net.minecraft.text.Text.literal(step==CreatorFlow.Step.REVIEW?"Finish Character":"Next"));pane=addDrawableChild(new CharacterCanvas(CharacterShell.workspace(layout,step==CreatorFlow.Step.REVIEW)));
        switch(step){
            case IDENTITY->CreatorWorkspace.identity(pane,textRenderer,state,this::inspect,this::build,()->custom("species","Race / subrace"));
            case CLASS->CreatorWorkspace.clazz(pane,state,this::inspect,this::build,()->custom("characterClass","Class"),()->go(CreatorFlow.Step.PROFICIENCIES),this::chooseClass);
            case ABILITIES->{if(text(state.snapshot(),"profile").equals("srd_5_1")){AbilityWorkspace.build(pane,textRenderer,state,this::build,busy,this::confirmMethod);}else pane.label("Imported profile: preserve its existing ability representation.",6,6,pane.getWidth()-12,RpgTheme.MUTED);}
            case REVIEW->CharacterSheetUi.build(pane,state.snapshot(),true,null,validation,null,this::go);
            default->pane.label("Loading "+step.title+" workspace…",6,6,pane.getWidth()-12,RpgTheme.MUTED);
        }
        if(pane!=null){pane.cursors(cursors.getOrDefault(step,Map.of()));pane.position(positions.getOrDefault(step,0));String key=focus.getOrDefault(step,"");if(!key.isEmpty()){pane.focus(key);setInitialFocus(pane);}}
    }
    private void inspect(FeatureReference.Entry e){client.setScreen(new FeatureInspectScreen(this,e));}
    private void custom(String field,String title){if(field.equals("characterClass")){if(!busy&&fresh)client.setScreen(new CustomClassNameScreen(this,state.fields.get(field),name->{resumed.queue(()->chooseClass(name));client.setScreen(this);}));return;}saveCurrent(()->client.setScreen(WizardEditors.customIdentity(this,state.snapshot(),field,title)));}
    private void chooseClass(String target){if(busy||!fresh)return;try{var prepared=ClassChangeIntent.prepare(state,target);if(prepared.isEmpty())return;var intent=prepared.get();if(!state.snapshot().has("classChangeAllowed")&&!intent.selected().isBlank()&&text(state.snapshot(),"mode").equals("GUIDED")){message="Update Cubetable on the server before changing a guided class.";return;}if(!flag(state.snapshot(),"classChangeAllowed")||intent.selected().isBlank()){state.fields.put("characterClass",intent.target());build();return;}client.setScreen(new RpgConfirmationScreen(this,"Change Class?","Changing "+intent.selected()+" to "+intent.target()+" resets class skill choices, Expertise, subclass and ability allocation. Race, identity, background and independently granted proficiencies are preserved.",()->resumed.queue(()->applyClassChange(intent))).labels("Cancel","Change Class").onCancel(()->{resumed.clear();message="Class change cancelled. All values retained.";}));}catch(IllegalArgumentException invalid){message=invalid.getMessage();}}
    private void applyClassChange(ClassChangeIntent intent){if(!fresh||busy||!intent.matches(state)){message="Character or allocation changed. Select the class again to review and confirm.";return;}unresolvedClassChange=intent;saveDraftRequest(LIBRARY_UPDATE,args("character",character,"revision",intent.revision(),"section","classChange","data",intent.data()),next->{state.acceptClassChange(next);unresolvedClassChange=null;validation=null;cursors.remove(CreatorFlow.Step.ABILITIES);message="Class changed. Guided choices and ability allocation reset.";build();return true;},()->{});}
    private void confirmMethod(WizardModel.ScoreMethod next){var intent=AbilityMethodChange.prepare(state,next);client.setScreen(new RpgConfirmationScreen(this,"Change ability method?",intent.explanation(),()->{if(intent.apply(state)){build();message="Method changed in this draft; Save Draft to confirm.";}else message="Scores or saved revision changed. Review before changing method.";}));}
    private void reload(){if(busy)return;request(LIBRARY_GET,args("character",character),r->{if(r.code().equals("OK")){var current=DraftReplies.snapshot(r.data(),character);boolean recovered=unresolvedClassChange!=null&&unresolvedClassChange.acknowledged(current);if(recovered)state.acceptClassChange(current);else state.accept(current,false);unresolvedClassChange=null;validation=DraftReplies.validationFromSnapshot(current);fresh=true;message=recovered?"Class change recovered. Old allocation cleared; fresh defaults loaded.":state.dirty()?"Unsaved edits retained. Save to confirm.":"Saved character loaded.";build();}else{fresh=false;message=r.message()+" Edits retained; refresh before saving.";}});}
    public void navigateFromChild(CreatorFlow.Step next){resumed.queue(()->go(next));client.setScreen(this);}
    public CreatorFlow.Step currentStep(){return step;}
    private void navigateTab(CreatorFlow.Step next){if(busy||!fresh)return;if(next!=step)saveCurrent(()->openStep(next));}
    private void go(CreatorFlow.Step next){saveCurrent(()->openStep(next));}
    private void openStep(CreatorFlow.Step next){remember();step=next;build();Screen editor=switch(next){case PROFICIENCIES->new ProficiencyPickerScreen(this,state.snapshot());case EQUIPMENT->new InventoryWorkspace(this,state.snapshot(),new DashboardSource(true,character));case FEATURES->new WizardRecordsScreen(this,state.snapshot(),"features");case SPELLS->new WizardRecordsScreen(this,state.snapshot(),"spellbook");case DETAILS->new CharacterDetailsScreen(this,state.snapshot());default->null;};if(editor!=null)client.setScreen(editor);else if(next==CreatorFlow.Step.REVIEW&&validation==null)reload();}
    private void saveCurrent(Runnable after){saveCurrent(after,step==CreatorFlow.Step.ABILITIES||step==CreatorFlow.Step.REVIEW);}
    private void saveCurrent(Runnable after,boolean includeScores){
        if(busy||!fresh){message="Refresh the saved character before saving.";return;}
        if(state.reviewRequired()){long reviewed=revision(state.snapshot());client.setScreen(new RpgConfirmationScreen(this,"Review concurrent edits","The saved character changed. Confirm applies the following proposed changes to this reviewed revision. Cancel keeps editing.\n\n"+proposedChanges(),()->{if(revision(state.snapshot())==reviewed){resumed.queueReviewed(reviewed,()->revision(state.snapshot()),()->{state.reviewed();saveCurrent(after,includeScores);},()->message="Character changed again; start a new save after reviewing.");}else message="Character changed again; review before saving.";}).onCancel(()->{resumed.clear();message="Save cancelled. Your edits are retained.";if(step!=CreatorFlow.Step.IDENTITY&&step!=CreatorFlow.Step.CLASS&&step!=CreatorFlow.Step.ABILITIES&&step!=CreatorFlow.Step.REVIEW)resumed.queue(()->openStep(step));}));return;}
        var snapshot=state.snapshot();
        if(!state.fields.get("name").equals(CreatorDraftState.savedField(snapshot,"name"))){save("basics",args("name",state.fields.get("name")),()->saveCurrent(after,includeScores));return;}
        if(List.of("species","age","height","alignment").stream().anyMatch(k->!state.fields.get(k).equals(CreatorDraftState.savedField(snapshot,k)))){save("identity",state.identityData(List.of("species","age","height","alignment")),()->saveCurrent(after,includeScores));return;}
        if(state.classDirty()){save("identity",state.identityData(List.of("characterClass")),()->saveCurrent(after,includeScores));return;}
        if(includeScores&&state.scoresDirty()){try{var scores=new JsonObject();state.scoreValues().forEach(scores::addProperty);save("abilityAllocation",args("abilities",scores,"method",state.method.name()),()->saveCurrent(after,includeScores));}catch(RuntimeException invalid){message=invalid.getMessage();messageColor=RpgTheme.ERROR;}return;}
        after.run();
    }
    private String proposedChanges(){var snap=state.snapshot();var out=new StringBuilder();for(String key:CreatorDraftState.FIELDS){String saved=CreatorDraftState.savedField(snap,key),staged=state.fields.get(key);if(!saved.equals(staged))out.append(key).append(": ").append(saved).append(" → ").append(staged).append('\n');}for(String key:CreatorDraftState.ABILITIES){String saved=CreatorDraftState.savedScore(snap,key),staged=state.scores.get(key);if(!saved.equals(staged))out.append(key.toUpperCase(Locale.ROOT)).append(": ").append(saved).append(" → ").append(staged).append('\n');}out.append("Ability method: ").append(state.method);return out.toString();}
    private void save(String section,JsonObject data,Runnable after){saveDraftRequest(LIBRARY_UPDATE,args("character",character,"revision",revision(state.snapshot()),"section",section,"data",data),next->{state.accept(next,true);validation=null;message="Draft saved.";build();return true;},after);}
    @Override protected void saveDraftRequest(dev.tacticalcombat.uiapi.UiApiService.Operation op,JsonObject args,java.util.function.Function<JsonObject,Boolean> accept,Runnable after){fresh=false;super.saveDraftRequest(op,args,next->{fresh=true;return accept.apply(next);},after);}
    private void finish(){saveCurrent(()->{long expected=revision(state.snapshot());request(LIBRARY_VALIDATE,args("character",character),r->{if(!r.code().equals("OK")){fresh=false;return;}if(revision(r.data())!=expected){fresh=false;message="Character changed during validation. Refresh and review before finishing.";return;}validation=DraftReplies.validation(r.data());if(!array(validation,"errors").isEmpty()){step=CreatorFlow.Step.REVIEW;message="Complete the missing step before finishing.";build();return;}int unused=r.data().get("unusedAbilityPoints").getAsInt();if(unused>0){client.setScreen(new RpgConfirmationScreen(this,unused+" Ability Points Remaining","You have "+unused+" unused ability points. Finish this character anyway?",()->resumed.queue(()->finalizeCurrent(expected,unused))).labels("Continue Editing","Finish Anyway").onCancel(()->resumed.queue(()->openStep(CreatorFlow.Step.ABILITIES))));}else finalizeCurrent(expected,null);});});}
    private void finalizeCurrent(long expected,Integer unused){if(!fresh||busy||state.dirty()||revision(state.snapshot())!=expected){message="Character changed; review and confirm the current revision before finishing.";return;}var request=args("character",character,"revision",expected);if(unused!=null)request.addProperty("confirmedUnusedPoints",unused);request(LIBRARY_FINALIZE,request,reply->{if(!reply.code().equals("OK")){fresh=false;return;}state.accept(DraftReplies.snapshot(reply.data(),character),true);client.setScreen(new ChoiceScreen(parent,"Character finished",List.of("Keep in My Library","Submit Independent Copy to Campaign"),s->s,s->{if(s.startsWith("Keep"))client.setScreen(CharacterDashboardScreen.library(parent,character));else client.setScreen(new LibraryCharacterScreen(parent,character).submitOnOpen());}));});}
    @Override public boolean keyPressed(int key,int scan,int mods){if(key==org.lwjgl.glfw.GLFW.GLFW_KEY_ESCAPE&&pane!=null&&pane.dismissPopup())return true;if(super.keyPressed(key,scan,mods))return true;if(key==org.lwjgl.glfw.GLFW.GLFW_KEY_ENTER&&pane!=null&&(CreatorDraftState.FIELDS.contains(pane.focusedKey())||CreatorDraftState.ABILITIES.contains(pane.focusedKey()))){saveCurrent(this::build);return true;}return false;}
    @Override public void tick(){super.tick();if(resumed.pending()&&fresh&&!busy){resumed.run();}}
    @Override protected void content(DrawContext g,int mx,int my,float delta){if(step==CreatorFlow.Step.REVIEW&&layout.compactSummary())return;var s=layout.summary();RpgTheme.panel(g,s.x(),s.y(),s.width(),s.height(),RpgTheme.PANEL,true);if(layout.compactSummary()){RpgTheme.text(g,textRenderer,"Saved: "+text(state.snapshot(),"name")+" · "+CreatorDraftState.savedField(state.snapshot(),"species")+" · "+CreatorDraftState.savedField(state.snapshot(),"characterClass"),s.x()+5,s.y()+(s.height()-9)/2,s.width()-10,RpgTheme.GOLD);}else{if(client.player!=null)PlayerSkinDrawer.draw(g,client.player.getSkinTextures(),s.x()+s.width()/2-12,s.y()+7,24);drawSavedSummary(g,s);}}
    private void drawSavedSummary(DrawContext g,UiLayout.Rect s){var snap=state.snapshot();String header="Saved character\n"+text(snap,"name")+"\n"+CreatorDraftState.savedField(snap,"species")+"\n"+CreatorDraftState.savedField(snap,"characterClass")+"\nLevel "+DashboardModel.xp(snap.getAsJsonObject("sheet")).level();int x=s.x()+8,y=s.y()+36,w=s.width()-16;for(String paragraph:header.split("\n"))for(var line:textRenderer.wrapLines(net.minecraft.text.Text.literal(paragraph),w)){if(y+9>s.y()+s.height()-6)return;g.drawText(textRenderer,line,x,y,RpgTheme.MUTED,false);y+=12;}y+=8;for(String key:CreatorDraftState.ABILITIES){if(y+9>s.y()+s.height()-6)return;String score=CreatorDraftState.savedScore(snap,key);g.drawText(textRenderer,key.toUpperCase(Locale.ROOT),x,y,RpgTheme.TEXT,false);g.drawText(textRenderer,score,x+w-textRenderer.getWidth(score),y,RpgTheme.GOLD,false);y+=14;}y+=8;if(y+9<s.y()+s.height()-6)RpgTheme.text(g,textRenderer,state.dirty()?"Unsaved preview edits":"Saved values",x,y,w,RpgTheme.MUTED);y+=14;if(y+9<s.y()+s.height()-6){long complete=CreatorFlow.statuses(snap).values().stream().filter(WizardModel.Status::complete).count();RpgTheme.text(g,textRenderer,"Sections complete: "+complete+" / "+CreatorFlow.Step.values().length,x,y,w,RpgTheme.MUTED);}}
    @Override public void close(){if(busy){message="Waiting for server acknowledgement.";return;}if(step.ordinal()>0){openStep(CreatorFlow.Step.values()[step.ordinal()-1]);return;}if(state.dirty())client.setScreen(new RpgConfirmationScreen(this,"Discard unsaved edits?","Previously acknowledged fields remain saved.",()->client.setScreen(parent)));else super.close();}
}
